import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import math

conv_transpose_kernel = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    int input_height,
    int input_width,
    int output_height,
    int output_width,
    bool has_bias
) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total_elements = batch_size * out_channels * output_height * output_width;
    if (idx >= total_elements) return;

    const int b = idx / (out_channels * output_height * output_width);
    const int oc = (idx / (output_height * output_width)) % out_channels;
    const int oh = (idx / output_width) % output_height;
    const int ow = idx % output_width;

    float val = 0.0f;

    for (int kh = 0; kh < kernel_size; ++kh) {
        for (int kw = 0; kw < kernel_size; ++kw) {
            const int ih = (oh + padding - kh * dilation) / stride;
            const int iw = (ow + padding - kw * dilation) / stride;

            if ((oh + padding - kh * dilation) % stride != 0) continue;
            if ((ow + padding - kw * dilation) % stride != 0) continue;
            if (ih < 0 || ih >= input_height || iw < 0 || iw >= input_width) continue;

            for (int ic = 0; ic < in_channels; ++ic) {
                const int input_idx = b * in_channels * input_height * input_width 
                                   + ic * input_height * input_width 
                                   + ih * input_width 
                                   + iw;
                const int weight_idx = ic * out_channels * kernel_size * kernel_size 
                                    + oc * kernel_size * kernel_size 
                                    + kh * kernel_size 
                                    + kw;
                val += input[input_idx] * weight[weight_idx];
            }
        }
    }

    if (has_bias) val += bias[oc];

    output[idx] = val;
}

torch::Tensor conv_transpose2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int output_height,
    int output_width,
    bool has_bias
) {
    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int input_height = input.size(2);
    const int input_width = input.size(3);
    const int out_channels = weight.size(1);
    const int kernel_size = weight.size(2);

    auto output = torch::zeros({batch_size, out_channels, output_height, output_width}, input.options());
    const int total_elements = output.numel();

    const int threads = 256;
    const int blocks = (total_elements + threads - 1) / threads;

    conv_transpose2d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        kernel_size,
        stride,
        padding,
        dilation,
        input_height,
        input_width,
        output_height,
        output_width,
        has_bias
    );

    return output;
}
"""

conv_transpose_cpp = """
torch::Tensor conv_transpose2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int output_height,
    int output_width,
    bool has_bias
);
"""

conv_transpose_module = load_inline(
    name="conv_transpose2d",
    cpp_sources=conv_transpose_cpp,
    cuda_sources=conv_transpose_kernel,
    functions=["conv_transpose2d_forward"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, 
                 stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

        self.weight = nn.Parameter(torch.Tensor(in_channels, out_channels, kernel_size, kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('bias', None)

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        _, _, h_in, w_in = x.shape
        h_out = (h_in - 1) * self.stride - 2 * self.padding + self.dilation * (self.kernel_size - 1) + 1
        w_out = (w_in - 1) * self.stride - 2 * self.padding + self.dilation * (self.kernel_size - 1) + 1

        return conv_transpose_module.conv_transpose2d_forward(
            x, 
            self.weight,
            self.bias if self.bias is not None else torch.empty(0),
            self.stride,
            self.padding,
            self.dilation,
            h_out,
            w_out,
            self.bias is not None
        )
